import random

GROUP = "algebra"
SKILL = "transformation"

def generate(seed):
    rng = random.Random(seed)

    # INVARIANT: m must stay a multiple of 4. The real optimum is a = b = c = d = m/4,
    # so the answer ((m + 4k)/4)^4 is an integer exactly when 4 | m. Keep the invariant
    # in the construction (4 * p), never in a value list.
    p = rng.randint(2, 10)          # free parameter; widen freely
    m = 4 * p                       # m in {8, 12, ..., 40}
    k = rng.randint(1, 6)           # k >= 1 keeps every factor positive

    assert m % 4 == 0 and k >= 1, (
        "invariant violated: m must stay a multiple of 4 and k >= 1"
    )

    max_product = (p + k) ** 4      # = ((m + 4k)/4)^4, exact since m = 4p

    # Independent route: search every positive integer quadruple summing to m.
    # Since 4 | m, the real optimum a = b = c = d = m/4 is a lattice point, so
    # the searched maximum must equal the formula.
    check = max(
        (a + k) * (b + k) * (c + k) * (m - a - b - c + k)
        for a in range(1, m - 3)
        for b in range(1, m - a - 1)
        for c in range(1, m - a - b)
    )
    assert max_product == check, f"max_product={max_product} check={check}"

    problem = (
        f"Let a, b, c, d be positive real numbers with a + b + c + d = {m}. "
        f"What is the maximum value of (a + {k})(b + {k})(c + {k})(d + {k})?"
    )

    return problem, str(max_product)
